-- Archive knowledge schema. Generated by go run ./cmd/knowledge-schema.
CREATE TABLE IF NOT EXISTS "knowledge_document_version" ("id" bigserial,"source_version_id" bigint NOT NULL,"document_id" bigint NOT NULL,"archive_id" bigint NOT NULL,"title" varchar(255),"sequence" bigint,"state" varchar(32),"markdown" TEXT,"summary" TEXT,"summary_state" varchar(32),"digest" varchar(64),"error" varchar(500),"attempts" bigint,"lease" varchar(64),"lease_until" bigint,"next_run" bigint,"updated_at" bigint,"summary_model" varchar(255) DEFAULT '',"summary_recipe" varchar(64) DEFAULT '',"parser_revision" varchar(32) DEFAULT '',"index_revision" varchar(32) DEFAULT '',PRIMARY KEY ("id"),CONSTRAINT "uni_knowledge_document_version_source_version_id" UNIQUE ("source_version_id"));
CREATE INDEX IF NOT EXISTS "idx_knowledge_document_version_state" ON "knowledge_document_version" ("state");
CREATE INDEX IF NOT EXISTS "idx_knowledge_document_version_archive_id" ON "knowledge_document_version" ("archive_id");
CREATE INDEX IF NOT EXISTS "idx_knowledge_document_version_document_id" ON "knowledge_document_version" ("document_id");
CREATE TABLE IF NOT EXISTS "knowledge_document_section" ("id" bigserial,"version_id" bigint NOT NULL,"position" bigint,"heading" varchar(255),"body" TEXT,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_knowledge_document_section_version_id" ON "knowledge_document_section" ("version_id");
CREATE TABLE IF NOT EXISTS "knowledge_document_workbook" ("version_id" bigint,"data" TEXT,PRIMARY KEY ("version_id"));
CREATE TABLE IF NOT EXISTS "knowledge_document_term" ("term" varchar(64),"section_id" bigint,"version_id" bigint NOT NULL,"weight" bigint NOT NULL,PRIMARY KEY ("term","section_id"));
CREATE INDEX IF NOT EXISTS "idx_knowledge_document_term_version_id" ON "knowledge_document_term" ("version_id");
CREATE TABLE IF NOT EXISTS "knowledge_document_derivation" ("section_id" bigint,"version_id" bigint NOT NULL,"source_digest" varchar(64),"recipe" varchar(64),"model" varchar(255),"state" varchar(32),"content" TEXT,"attempts" bigint,"next_run" bigint,"error" varchar(500),PRIMARY KEY ("section_id"));
CREATE INDEX IF NOT EXISTS "idx_knowledge_document_derivation_version_id" ON "knowledge_document_derivation" ("version_id");
